  const handleDownloadEmptyCsvHeader = () => {
    const headerOnly = 'student_code,full_name,gender,date_of_birth,group_number,position,parent_name,parent_phone,address,notes\n';
    const blob = new Blob(['\uFEFF' + headerOnly], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'khung_danh_sach_hoc_sinh_lop_5_4.csv';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  // Xuất danh sách học sinh hiện có trên Supabase ra file CSV
  const handleExportStudentsCsv = () => {
    if (students.length === 0) {
      showNotice('Hiện chưa có học sinh nào trong cơ sở dữ liệu để xuất file.', 'error');
      return;
    }
    const headers = [
      'student_code', 'full_name', 'gender', 'date_of_birth',
      'group_number', 'position', 'parent_name', 'parent_phone', 'address', 'status', 'notes'
    ];
    const escapeCsv = (val) => {
      if (val === null || val === undefined) return '';
      const s = String(val).replace(/"/g, '""');
      return s.includes(',') || s.includes('\n') ? `"${s}"` : s;
    };
    const rows = students.map((st) => headers.map((h) => escapeCsv(st[h])).join(','));
    const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'danh_sach_hoc_sinh_lop_5_4.csv';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

