  // --- TÍNH TOÁN DỮ LIỆU ĐỒNG BỘ TỪ DB ---
  const filteredStudents = useMemo(() => {
    return students.filter((st) => {
      const matchGroup =
        studentGroupFilter === 'ALL' || Number(st.group_number) === Number(studentGroupFilter);
      const matchStatus =
        studentStatusFilter === 'ALL' || st.status === studentStatusFilter;
      const q = studentSearch.trim().toLowerCase();
      const matchQuery =
        !q ||
        (st.full_name || '').toLowerCase().includes(q) ||
        (st.student_code || '').toLowerCase().includes(q) ||
        (st.parent_name || '').toLowerCase().includes(q) ||
        (st.parent_phone || '').toLowerCase().includes(q);
      return matchGroup && matchStatus && matchQuery;
    });
  }, [students, studentGroupFilter, studentStatusFilter, studentSearch]);

  const filteredAnnouncements = useMemo(() => {
    return announcements.filter((a) => {
      if (announcementCategoryFilter === 'ALL') return true;
      return a.category === announcementCategoryFilter;
    });
  }, [announcements, announcementCategoryFilter]);

  const filteredCompetitionRecords = useMemo(() => {
    if (selectedWeekId === 'ALL') return competitionRecords;
    return competitionRecords.filter((r) => r.week_id === selectedWeekId);
  }, [competitionRecords, selectedWeekId]);

  // Tính bảng xếp hạng 4 Tổ từ dữ liệu thực
  const groupRankings = useMemo(() => {
    const selectedWeekObj = academicWeeks.find((w) => w.id === selectedWeekId);
    const basePoints =
      selectedWeekId === 'ALL'
        ? Math.max(academicWeeks.length, 1) * 100
        : Number(selectedWeekObj?.base_points || 100);

    const groups = [1, 2, 3, 4].map((gNum) => {
      const memberCount = students.filter((s) => Number(s.group_number) === gNum).length;
      const recs = filteredCompetitionRecords.filter((r) => Number(r.group_number) === gNum);
      const bonus = recs
        .filter((r) => Number(r.points_delta) > 0)
        .reduce((acc, r) => acc + Number(r.points_delta), 0);
      const penalty = recs
        .filter((r) => Number(r.points_delta) < 0)
        .reduce((acc, r) => acc + Number(r.points_delta), 0);
      const total = basePoints + bonus + penalty;
      return {
        group_number: gNum,
        memberCount,
        basePoints,
        bonus,
        penalty,
        total,
        recordCount: recs.length
      };
    });

    return groups.sort((a, b) => b.total - a.total);
  }, [students, academicWeeks, selectedWeekId, filteredCompetitionRecords]);

  // Tính bảng xếp hạng cá nhân học sinh từ dữ liệu thực
  const studentLeaderboard = useMemo(() => {
    const scoreMap = new Map();
    filteredCompetitionRecords.forEach((rec) => {
      if (!rec.student_id) return;
      const prev = scoreMap.get(rec.student_id) || {
        student_id: rec.student_id,
        student_name: rec.student_name || 'Học sinh',
        group_number: rec.group_number,
        totalDelta: 0,
        plusCount: 0,
        minusCount: 0
      };
      const delta = Number(rec.points_delta) || 0;
      prev.totalDelta += delta;
      if (delta > 0) prev.plusCount += 1;
      if (delta < 0) prev.minusCount += 1;
      scoreMap.set(rec.student_id, prev);
    });
    return Array.from(scoreMap.values()).sort((a, b) => b.totalDelta - a.totalDelta);
  }, [filteredCompetitionRecords]);

  const filteredPhotos = useMemo(() => {
    if (selectedAlbumId === 'ALL') return activityPhotos;
    return activityPhotos.filter((p) => p.album_id === selectedAlbumId);
  }, [activityPhotos, selectedAlbumId]);

  const handleCopySql = async () => {
    try {
      await navigator.clipboard.writeText(FULL_SQL_SCRIPT);
      setCopiedSql(true);
      showNotice('Đã sao chép toàn bộ câu lệnh SQL vào bộ nhớ tạm!');
      setTimeout(() => setCopiedSql(false), 3000);
    } catch (err) {
      const textarea = document.createElement('textarea');
      textarea.value = FULL_SQL_SCRIPT;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      setCopiedSql(true);
      showNotice('Đã sao chép toàn bộ câu lệnh SQL!');
      setTimeout(() => setCopiedSql(false), 3000);
    }
  };

