                  <option value="ALL">Tất cả Album hoạt động ({activityPhotos.length} ảnh)</option>
                  {activityAlbums.map((alb) => (
                    <option key={alb.id} value={alb.id}>
                      {alb.title}
                    </option>
                  ))}
